#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

int H[MAXN];
int max_left[MAXN];
int max_right[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &H[i]);
    }

    int current_max = 0;
    for (int i = 0; i < n; i++) {
        if (H[i] > current_max) {
            current_max = H[i];
        }
        max_left[i] = current_max;
    }

    current_max = 0;
    for (int i = n - 1; i >= 0; i--) {
        if (H[i] > current_max) {
            current_max = H[i];
        }
        max_right[i] = current_max;
    }

    int covered_sections = 0;
    for (int i = 0; i < n; i++) {
        int water_level = max_left[i] < max_right[i] ? max_left[i] : max_right[i];
        if (water_level > H[i]) {
            covered_sections++;
        }
    }

    printf("%d\n", covered_sections);

    return 0;
}
